{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.prepack_visibility AS WITH prepack_base AS ( SELECT ROW_NUMBER() OVER ( ORDER BY SKU_GROUP_, PO_NUMBER_, pre_pack_qty, QC_DATE, NO_OF_PREPACKS_QC_, AVG_DEPTH ) AS BASE_ROW_ID, SKU_GROUP_ AS SKU_GROUP, PO_NUMBER_ AS PO_NUMBER, CASE WHEN UPPER(TRIM(WAREHOUSE)) IN ( \'TAURU\', \'NORTH\', \'SAPL-NORTH-TAURU\' ) THEN \'NORTH\' WHEN UPPER(TRIM(WAREHOUSE)) IN ( \'YELAHANKA - 2\', \'SOUTH\', \'SAPL-WH2\' ) THEN \'SOUTH\' ELSE UPPER(TRIM(WAREHOUSE)) END AS WAREHOUSE, pre_pack_qty AS production_prepack_qty, QC_DATE AS INSPECTION_DATE, NO_OF_PREPACKS_QC_, AVG_DEPTH AS DEPTH, NO_OF_PREPACKS_QC_ * AVG_DEPTH AS PREPACK_QTY FROM SNITCH_DB.MAPLEMONK.PREPACK_TRACKER WHERE SKU_GROUP_ IS NOT NULL ), online_goods_dedup AS ( SELECT UPPER(TRIM(SKU)) AS SKU_GROUP, UPPER(TRIM(\"Logic PO\")) AS PO_NUMBER, VENDOR, WAREHOUSE, DELIVEY_DATE AS ALLOCATION_DATE FROM SNITCH_DB.MAPLEMONK.ONLINE_GOODS_MAIN QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(SKU)), UPPER(TRIM(\"Logic PO\")) ORDER BY COALESCE( TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'DD MON YY\'), TRY_TO_DATE(TRIM(DELIVEY_DATE), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(DELIVEY_DATE)) ) DESC NULLS LAST ) = 1 ), base AS ( SELECT p.BASE_ROW_ID, p.SKU_GROUP, p.PO_NUMBER, p.INSPECTION_DATE, p.NO_OF_PREPACKS_QC_, p.DEPTH, p.PREPACK_QTY, p.production_prepack_qty, o.VENDOR, p.WAREHOUSE, o.ALLOCATION_DATE, UPPER( TRIM( REGEXP_REPLACE( REGEXP_REPLACE( REGEXP_REPLACE( o.VENDOR, \'[\\r\\n\\t]+\', \' \' ), \'\\s+\', \' \' ), \'\\s*-\\s*[^-]+$\', \'\' ) ) ) AS vendor_clean FROM prepack_base p LEFT JOIN online_goods_dedup o ON UPPER(TRIM(p.SKU_GROUP)) = o.SKU_GROUP AND UPPER(TRIM(p.PO_NUMBER)) = o.PO_NUMBER ), vendor_mapping AS ( SELECT b.*, CASE WHEN vendor_clean IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\', \'KESAVAM CLOTHING PRIVATE LIMITED\', \'ADITYA INTERNATIONAL\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'GS CLOTHING\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'SUBHASH POLYTEX LIMITED\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'north\' WHEN vendor_clean IN ( \'TEXPORT INDUSTRIES PVT LTD\', \'ANUVARTHH APPARELS PVT.LTD.\', \'BBI\', \'BLUE MONKEY CLOTHING COMPANY\', \'G G GARMENTS\', \'K P GARMENT HOUSE\', \'KHARVA APPARELS\', \'LEANDRO FASHION\', \'LOHITH CREATIONS\', \'MARQUEE INDUSTRIES PVT LTD\', \'MAX KNITS INC\', \'MSQ CLOTHING LLP\', \'NALANDA DESIGNERS\', \'OM SHIVA SHAKTHI ENTERPRISES\', \'SAI TEXTILES\', \'SRI SAI TEJA CREATION\', \'V D DECORS\', \'VASUKI CREATIONS\', \'VIGNESH APPEARLS\', \'VIGNESH CREATIONS\', \'VIJAY RAM CREATIONS\', \'AMITHRAJ APPARELS\', \'KNOSKIN FASHIONS PVT. LTD\', \'VR CREATIONS\', \'ABHAY APPARELS\', \'AXCELLER\', \'DIVINITEE GENESIS APPAREL PVT LTD\', \'G T EXPORTS\', \'GO GO INTERNATIONAL PRIVATE LTD\', \'HEVIN CLOTHING\', \'KHATUSHREE INDIA\', \'KP PRODUCTION HOUSE LLP\', \'M SQUARE\', \'PRESTEIGE APPAREL PVT LTD\', \'S R APPARELS\', \'SAI TEXTILES SHADEZ\', \'TRIO APPARELS INDIA PVT. LTD\', \'V D FASHIONS\', \'NAVKAR AGENCY\', \'PRANAV INTERNATIONAL KNITWEAR\', \'THANDEESHWARA FASHIONS\', \'ORCHID CLOTH COMPANY\', \'HANUMAN TEXTILES\', \'ADDON CLOTHING\', \'CHECK MATE\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'ETTRO\', \'GROOVY FASHIONS\', \'LAMSOLEE CLOTHING COMPANY\', \'RAUNAK TEXTILES\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISHNU TRADING CO.\', \'VISTA GLOBAL COMPANY\', \'CUT AND SEW EXPORTS\', \'VEEYA FASHION\', \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'A N ASSOCIATES\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'CORE INDIA\', \'GO GO INTERNATIONAL PRIVATE LIMITED\', \'MOTIF CLOTHING CO.\', \'V.D.FASHIONS\', \'WALT ENTERPRISES\', \'VINTAGE\', \'THANDEESWARA FASHIONS\', \'SMART CLOTHING\', \'SILVER SPARK APPAREL LIMITED\' ) THEN \'south\' ELSE NULL END AS vendor_region FROM base b ), vendor_location_mapping AS ( SELECT v.*, CASE WHEN vendor_clean IN ( \'INDIAN CONNECTION\', \'KARMA (GU)\', \'ACME INTERNATIONAL LTD\', \'INTENSE FOCUS ITECH PRIVATE LIMITED\', \'POOJA FASHION\', \'AROMA DE FRANCE\', \'GENTEX GLOBAL\', \'A ONE KNITWEARS\', \'STELLA INDUSSTRIES LIMITED\', \'MAXVALUE CREATIONS PRIVATE LIMITED\', \'ADEES EXPORTS\', \'ELYSIUM FOOTWEAR CONCEPT PVT LTD\', \'LEATHER LUXURY\', \'SP INTERNATIONAL\', \'DESHNOK INNOVATOR\', \'INDIA BRAIDS PVT LTD\', \'KRISHNA BEADS INDUSTRIES\', \'MODELAMA EXPORTS (P) LTD\', \'AMPH FASHION PVT. LTD\', \'SHREEJI GARMENTS MANUFACTURING PVT LTD\', \'ASM INDUSTRIES (INDIA) PVT. LTD.\', \'B D SILK INDUSTRIES PVT. LTD\', \'KARMA (MU)\', \'THIMBLERR COMMERCE AND TECHNOLOGY PVT LTD\', \'EURO SUITS MANUFACTURING CO PRIVATE LIMITED\' ) THEN \'delhi\' WHEN vendor_clean IN ( \'SUBHASH POLYTEX LIMITED\', \'ADITYA INTERNATIONAL\', \'ANKUSH KNITTING WORKS PRIVATE LIMITED\', \'EVELINE INTERNATIONAL\', \'GOOD GOOD WEARS\', \'MAITRI KNITWEAR\', \'MANGLAM COLORS PRIVATE LIMITED\', \'MINERVA FASHION PVT LTD\', \'NEW MIGLANI HOSIERY FACTORY\', \'OBERAI KNITWEAR\', \'SHIVAAY KNITWEAR\', \'SHREE KRISHNA ENTERPRISES\', \'GS CLOTHING\', \'DHRUV APPARELS\', \'SAMBHAV CAP CREATION\' ) THEN \'ludhiana\' WHEN vendor_clean = \'KESAVAM CLOTHING PRIVATE LIMITED\' THEN \'kolkata\' WHEN vendor_clean IN ( \'PADMA SHRI KNIT WEAR\', \'VP KNIT FASHIONS\', \'INDIANA PUNTOS CLOTHING\', \'ASIAN CLOTHINGS\', \'VANITHA GARMENTS\', \'WEAREVER\', \'S R APPARELS\' ) THEN \'tirrupur\' WHEN vendor_clean IN ( \'ADDON CLOTHING\', \'CHILLCARE APPARELS PRIVATE LIMITED\', \'LAMSOLEE CLOTHING COMPANY\', \'RENAISSANCE FASHIONS\', \'SAANVI TRADERS\', \'VISTA GLOBAL COMPANY\' ) THEN \'mumbai\' WHEN vendor_region = \'south\' THEN \'bangalore\' ELSE NULL END AS vendor_location FROM vendor_mapping v ), north_inward_raw AS ( SELECT CASE WHEN UPPER(TRIM(sku_no)) LIKE \'MP%\' AND UPPER(TRIM(sku_no)) NOT LIKE \'MP-%\' THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_no)), 3) WHEN REGEXP_LIKE( UPPER(TRIM(sku_no)), \'.*-[0-9]$\' ) THEN REGEXP_REPLACE( UPPER(TRIM(sku_no)), \'-([0-9])$\', \'-0\\1\' ) ELSE UPPER(TRIM(sku_no)) END AS sku_group, COALESCE( TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YY\'), TRY_TO_DATE(PLANNED_DATE, \'YYYY-MM-DD\') ) AS planned_date, COALESCE( TRY_TO_DATE(actual_delivered_date, \'DD/MM/YYYY\'), TRY_TO_DATE(actual_delivered_date, \'DD-MM-YYYY\'), TRY_TO_DATE(actual_delivered_date, \'DD-MON-YYYY\'), TRY_TO_DATE(actual_delivered_date, \'DD MON YYYY\'), TRY_TO_DATE(actual_delivered_date, \'DD-MON-YY\'), TRY_TO_DATE(actual_delivered_date) ) AS actual_delivered_date, COALESCE( TRY_TO_DATE(TRIM(considered_delivered_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD MON YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date)) ) AS considered_delivered_date FROM SNITCH_DB.MAPLEMONK.TAURU_INWARD_DETAILS_SKU_LEVEL ), north_inward AS ( SELECT * FROM north_inward_raw QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, planned_date ORDER BY considered_delivered_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ), south_inward_raw AS ( SELECT CASE WHEN UPPER(TRIM(sku_no)) LIKE \'MP%\' AND UPPER(TRIM(sku_no)) NOT LIKE \'MP-%\' THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_no)), 3) WHEN REGEXP_LIKE( UPPER(TRIM(sku_no)), \'.*-[0-9]$\' ) THEN REGEXP_REPLACE( UPPER(TRIM(sku_no)), \'-([0-9])$\', \'-0\\1\' ) ELSE UPPER(TRIM(sku_no)) END AS sku_group, COALESCE( TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MON-YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD/MM/YY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(PLANNED_DATE, \'DD-MM-YY\'), TRY_TO_DATE(PLANNED_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(PLANNED_DATE, \'DD MON YYYY\') ) AS planned_date, COALESCE( CASE WHEN REGEXP_LIKE( TRIM(actual_delivered_date), \'^[0-9]{1,2}-[A-Za-z]{3}-[0-9]{2}$\' ) THEN DATE_FROM_PARTS( 2000 + TO_NUMBER(RIGHT(TRIM(actual_delivered_date), 2)), MONTH( TRY_TO_DATE( UPPER( SPLIT_PART( TRIM(actual_delivered_date), \'-\', 2 ) ), \'MON\' ) ), TO_NUMBER( SPLIT_PART( TRIM(actual_delivered_date), \'-\', 1 ) ) ) END, CASE WHEN REGEXP_LIKE( TRIM(actual_delivered_date), \'^[0-9]{1,2} [A-Za-z]{3} [0-9]{2}$\' ) THEN DATE_FROM_PARTS( 2000 + TO_NUMBER(RIGHT(TRIM(actual_delivered_date), 2)), MONTH( TRY_TO_DATE( UPPER( SPLIT_PART( TRIM(actual_delivered_date), \' \', 2 ) ), \'MON\' ) ), TO_NUMBER( SPLIT_PART( TRIM(actual_delivered_date), \' \', 1 ) ) ) END, TRY_TO_DATE( UPPER( REGEXP_REPLACE( TRIM(actual_delivered_date), \'\\s+\', \' \' ) ), \'DD MON YYYY\' ), TRY_TO_DATE( UPPER( REGEXP_REPLACE( TRIM(actual_delivered_date), \'\\s+\', \' \' ) ), \'DD-MON-YYYY\' ), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(actual_delivered_date), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(actual_delivered_date)) ) AS actual_delivered_date, COALESCE( TRY_TO_DATE(TRIM(considered_delivered_date), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD MON YY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(considered_delivered_date)) ) AS considered_delivered_date FROM SNITCH_DB.MAPLEMONK.SOUTH_INWARD_DETAILS_SKU_LEVEL ), south_inward AS ( SELECT * FROM south_inward_raw QUALIFY ROW_NUMBER() OVER ( PARTITION BY sku_group, planned_date ORDER BY considered_delivered_date DESC NULLS LAST, actual_delivered_date DESC NULLS LAST ) = 1 ), delivery_mapping AS ( SELECT v.*, CASE WHEN UPPER(TRIM(v.WAREHOUSE)) LIKE \'%NORTH%\' THEN ni.actual_delivered_date WHEN UPPER(TRIM(v.WAREHOUSE)) LIKE \'%SOUTH%\' THEN si.actual_delivered_date ELSE NULL END AS actual_delivered_date, CASE WHEN UPPER(TRIM(v.WAREHOUSE)) LIKE \'%NORTH%\' THEN ni.considered_delivered_date WHEN UPPER(TRIM(v.WAREHOUSE)) LIKE \'%SOUTH%\' THEN si.considered_delivered_date ELSE NULL END AS delivered_date FROM vendor_location_mapping v LEFT JOIN north_inward ni ON UPPER(TRIM(v.SKU_GROUP)) = UPPER(TRIM(ni.sku_group)) AND COALESCE( TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD MON YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE)) ) = ni.planned_date AND UPPER(TRIM(v.WAREHOUSE)) LIKE \'%NORTH%\' LEFT JOIN south_inward si ON UPPER(TRIM(v.SKU_GROUP)) = UPPER(TRIM(si.sku_group)) AND COALESCE( TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'DD MON YY\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(v.ALLOCATION_DATE)) ) = si.planned_date AND UPPER(TRIM(v.WAREHOUSE)) LIKE \'%SOUTH%\' ), putaway_dates AS ( SELECT BASE_ROW_ID, putaway_date AS inward_date FROM ( SELECT dm.BASE_ROW_ID, dm.sku_group, dm.warehouse, p.putaway_completed_date::DATE AS putaway_date, SUM( TRY_TO_NUMBER(p.putaway_completed_quantity) ) OVER ( PARTITION BY dm.BASE_ROW_ID, p.putaway_completed_date::DATE ) AS daily_qty FROM delivery_mapping dm JOIN SNITCH_DB.MAPLEMONK.PUTAWAY_TRACKING p ON UPPER(TRIM(dm.sku_group)) = CASE WHEN UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'SN%\' OR UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER( TRIM(p.\"Item Type skuCode\") ) WHEN UPPER(TRIM(p.\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER( TRIM( REGEXP_SUBSTR( p.\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\' ) ) ) ELSE UPPER( TRIM( COALESCE( REGEXP_SUBSTR( p.\"Item Type skuCode\"::STRING, \'^[^-]+-[^-]+\', 1, 1 ), p.\"Item Type skuCode\"::STRING ) ) ) END AND ( ( UPPER(TRIM(dm.warehouse)) LIKE \'%NORTH%\' AND p.\"Warehouse Name\" = \'SAPL-NORTH-TAURU\' ) OR ( UPPER(TRIM(dm.warehouse)) LIKE \'%SOUTH%\' AND p.\"Warehouse Name\" = \'SAPL-WH2\' ) ) WHERE p.final_type = \'New Inward\' AND dm.actual_delivered_date IS NOT NULL AND p.putaway_completed_date::DATE >= dm.actual_delivered_date ) QUALIFY ROW_NUMBER() OVER ( PARTITION BY BASE_ROW_ID ORDER BY daily_qty DESC, putaway_date DESC ) = 1 ), uc_item_master AS ( SELECT UPPER(TRIM(im.sku)) AS pp_code, SPLIT_PART(UPPER(TRIM(im.sku)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(im.sku)), \'-\', 3) AS sku_group, im.updated AS item_master_updated FROM SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER im WHERE im.name ILIKE \'kit%\' AND im.sku ILIKE \'PP%\' AND NOT ( ( SPLIT_PART(UPPER(TRIM(im.sku)), \'-\', 2) || \'-\' || SPLIT_PART(UPPER(TRIM(im.sku)), \'-\', 3) ) = \'4JE131-03\' AND REGEXP_LIKE( UPPER(TRIM(im.sku)), \'^PP16-4JE131-03-[0-9]{4}-[0-9]+$\', \'i\' ) ) ), uc_pp_code_warehouse AS ( SELECT UPPER(TRIM(u.\"Item SkuCode\")) AS pp_code, SPLIT_PART( UPPER(TRIM(u.\"Item SkuCode\")), \'-\', 2 ) || \'-\' || SPLIT_PART( UPPER(TRIM(u.\"Item SkuCode\")), \'-\', 3 ) AS sku_group, UPPER(TRIM(u.facility)) AS facility, MAX(im.updated) AS uc_updated_at FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_LIVE_INVENTORY u INNER JOIN SNITCH_DB.MAPLEMONK.UC_FINAL_ITEM_MASTER im ON UPPER(TRIM(u.\"Item SkuCode\")) = UPPER(TRIM(im.sku)) WHERE u.\"Item SkuCode\" ILIKE \'PP%\' AND NULLIF(TRIM(u.facility), \'\') IS NOT NULL GROUP BY 1, 2, 3 ), uc_inward_dates AS ( SELECT UPPER(TRIM(q.sku_group)) AS sku_group, CASE WHEN UPPER(TRIM(q.facility)) = \'SAPL-NORTH-TAURU\' THEN \'NORTH\' WHEN UPPER(TRIM(q.facility)) = \'SAPL-WH2\' THEN \'SOUTH\' ELSE UPPER(TRIM(q.facility)) END AS warehouse, MAX(p.uc_updated_at)::DATE AS uc_inward_date FROM SNITCH_DB.MAPLEMONK.PREPACK_SO_TRACKER_UC_SKU q LEFT JOIN uc_pp_code_warehouse p ON UPPER(TRIM(q.sku_group)) = p.sku_group AND UPPER(TRIM(q.facility)) = p.facility GROUP BY 1, 2 ), final_data AS ( SELECT dm.*, pd.inward_date, uid.uc_inward_date, q.inventory AS inventory, q.depth AS uc_depth, COALESCE(q.prepacks_left, 0) AS prepacks_left, q.prepack_fill_rate AS prepack_fill_rate FROM delivery_mapping dm LEFT JOIN putaway_dates pd ON dm.BASE_ROW_ID = pd.BASE_ROW_ID LEFT JOIN uc_inward_dates uid ON UPPER(TRIM(dm.sku_group)) = uid.sku_group AND UPPER(TRIM(dm.warehouse)) = uid.warehouse LEFT JOIN SNITCH_DB.MAPLEMONK.PREPACK_SO_TRACKER_UC_SKU q ON UPPER(TRIM(dm.sku_group)) = UPPER(TRIM(q.sku_group)) AND UPPER(TRIM(dm.warehouse)) = CASE WHEN UPPER(TRIM(q.facility)) = \'SAPL-NORTH-TAURU\' THEN \'NORTH\' WHEN UPPER(TRIM(q.facility)) = \'SAPL-WH2\' THEN \'SOUTH\' ELSE UPPER(TRIM(q.facility)) END ), meta_mapping_dedup AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, l1_category, category, meta1, meta2, meta3 FROM SNITCH_DB.MAPLEMONK.META_MAPPING_COGS_SKU_2 QUALIFY ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(sku_group)) ORDER BY ( IFF(l1_category IS NOT NULL, 1, 0) + IFF(category IS NOT NULL, 1, 0) + IFF(meta1 IS NOT NULL, 1, 0) + IFF(meta2 IS NOT NULL, 1, 0) + IFF(meta3 IS NOT NULL, 1, 0) ) DESC, l1_category, category, meta1, meta2, meta3 ) = 1 ), cp AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(lot_number)) AS po_number, MAX(po_cp) AS po_cp FROM snitch_db.maplemonk.logic_purchase_order GROUP BY 1, 2 ), enriched_final AS ( SELECT f.*, m.l1_category, m.category, m.meta1, m.meta2, m.meta3, cp.po_cp, cp.po_cp * f.depth AS prepack_cp FROM final_data f LEFT JOIN meta_mapping_dedup m ON UPPER(TRIM(f.sku_group)) = m.sku_group LEFT JOIN cp ON UPPER(TRIM(f.sku_group)) = cp.sku_group AND UPPER(TRIM(f.po_number)) = cp.po_number ) , style_inward_counts AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-[0-9]{2}$\', \'\') AS style_key, COUNT(DISTINCT UPPER(TRIM(sku_group))) AS prepack_sku_count, COUNT(DISTINCT CASE WHEN uc_inward_date IS NOT NULL THEN UPPER(TRIM(sku_group)) END) AS inwarded_sku_count FROM enriched_final GROUP BY 1 ), warehouse_inward_counts AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-[0-9]{2}$\', \'\') AS style_key, UPPER(TRIM(warehouse)) AS warehouse_key, COUNT(DISTINCT UPPER(TRIM(sku_group))) AS prepack_warehouse_count, COUNT(DISTINCT CASE WHEN uc_inward_date IS NOT NULL THEN UPPER(TRIM(sku_group)) END) AS inwarded_warehouse_count FROM enriched_final GROUP BY 1, 2 ), warehouse_mismatch AS ( SELECT style_key, MAX(IFF(prepack_warehouse_count <> inwarded_warehouse_count, 1, 0)) AS has_warehouse_pending FROM warehouse_inward_counts GROUP BY 1 ) SELECT SKU_GROUP, L1_CATEGORY, CATEGORY, META1, META2, META3, PO_NUMBER, PRODUCTION_PREPACK_QTY, INSPECTION_DATE, NO_OF_PREPACKS_QC_, PREPACK_QTY, PO_CP, PREPACK_CP, VENDOR, WAREHOUSE, ALLOCATION_DATE, depth, UPPER(vendor_region) AS VENDOR_REGION, UPPER(vendor_location) AS VENDOR_LOCATION, CASE WHEN UPPER(TRIM(WAREHOUSE)) LIKE \'%NORTH%\' THEN CASE vendor_location WHEN \'delhi\' THEN 1 WHEN \'bangalore\' THEN 7 WHEN \'ludhiana\' THEN 2 WHEN \'tirrupur\' THEN 9 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 5 ELSE NULL END WHEN UPPER(TRIM(WAREHOUSE)) LIKE \'%SOUTH%\' THEN CASE vendor_location WHEN \'delhi\' THEN 7 WHEN \'bangalore\' THEN 1 WHEN \'ludhiana\' THEN 8 WHEN \'tirrupur\' THEN 2 WHEN \'mumbai\' THEN 6 WHEN \'kolkata\' THEN 6 ELSE NULL END ELSE NULL END AS EXPECTED_TAT, DATEDIFF( day, COALESCE( TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD/MM/YYYY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD/MM/YY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD-MM-YY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD-MON-YY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'DD MON YYYY\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(ALLOCATION_DATE)) ), COALESCE( DELIVERED_DATE, CURRENT_DATE ) ) AS ALLOCATION_AGEING, DELIVERED_DATE, INWARD_DATE, UC_INWARD_DATE, INVENTORY, ROUND( CASE WHEN INWARD_DATE IS NOT NULL THEN INVENTORY * UC_DEPTH ELSE 0 END ) AS DEPTH_INVENTORY, UC_DEPTH, PREPACKS_LEFT, PREPACK_FILL_RATE, CASE WHEN UC_INWARD_DATE IS NOT NULL THEN \'INWARDED\' WHEN DELIVERED_DATE IS NOT NULL THEN \'DELIVERED\' WHEN ALLOCATION_DATE IS NOT NULL THEN \'IN_TRANSIT\' WHEN INSPECTION_DATE IS NOT NULL THEN \'RTS\' ELSE NULL END AS STATUS, CASE WHEN sc.prepack_sku_count > sc.inwarded_sku_count THEN \'COLOURS_PENDING\' WHEN COALESCE(wm.has_warehouse_pending, 0) = 1 THEN \'INWARD_PENDING_IN_BOTH_WAREHOUSES\' WHEN sc.prepack_sku_count = sc.inwarded_sku_count AND COALESCE(wm.has_warehouse_pending, 1) = 0 THEN \'READY_TO_ALLOCATE\' ELSE NULL END AS RECONCILIATION_STATUS FROM enriched_final e LEFT JOIN style_inward_counts sc ON REGEXP_REPLACE(UPPER(TRIM(e.sku_group)), \'-[0-9]{2}$\', \'\') = sc.style_key LEFT JOIN warehouse_mismatch wm ON REGEXP_REPLACE(UPPER(TRIM(e.sku_group)), \'-[0-9]{2}$\', \'\') = wm.style_key;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            